insert into public.vocabulary_words (id, lesson_id, sort_order, content) values
  ('w1', 'lesson1', 1, '{"id":"w1","word":"contract","familyWords":["contractor","contractual"],"phonetic":"/ˈkɑːn.trækt/","meaning":"a binding agreement enforceable by law","vietnameseMeaning":"hợp đồng (một thỏa thuận ràng buộc về pháp lý)","example":"We signed a contract for the project.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/contract_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1554224155-6726b3ff858f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"noun"}'::jsonb),
  ('w2', 'lesson1', 2, '{"id":"w2","word":"assurance","familyWords":["assure","reassurance"],"phonetic":"/əˈʃʊr.əns/","meaning":"a binding commitment to do or give or refrain from something","vietnameseMeaning":"sự đảm bảo (một cam kết ràng buộc để làm hoặc cho hoặc kiêng làm điều gì đó)","example":"The manager gave assurance of success.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/assurance_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1559757148-5c350d0d3c56?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"noun"}'::jsonb),
  ('w3', 'lesson1', 3, '{"id":"w3","word":"determine","familyWords":["determination","determinant"],"phonetic":"/dɪˈtɜːr.mɪn/","meaning":"find out or learn with certainty, as by making an inquiry","vietnameseMeaning":"xác định (tìm ra hoặc học được một cách chắc chắn, như bằng cách hỏi)","example":"We must determine the best approach.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/determine_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w4', 'lesson1', 4, '{"id":"w4","word":"engage","familyWords":["engagement","engaging"],"phonetic":"/ɪnˈɡeɪdʒ/","meaning":"consume all of one''s attention or time","vietnameseMeaning":"tham gia (tiêu thụ toàn bộ sự chú ý hoặc thời gian của ai đó)","example":"The speaker engaged the audience with his talk.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/engage_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1521737604893-d14cc237f11d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w5', 'lesson1', 5, '{"id":"w5","word":"establish","familyWords":["establishment","established"],"phonetic":"/ɪˈstæb.lɪʃ/","meaning":"set up or found","vietnameseMeaning":"thiết lập (xây dựng hoặc thành lập)","example":"The company established a new branch.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/establish_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1552664730-d307ca884978?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w6', 'lesson1', 6, '{"id":"w6","word":"provision","familyWords":["provide","provisional"],"phonetic":"/prəˈvɪʒ.ən/","meaning":"the activity of supplying something","vietnameseMeaning":"sự cung cấp (hoạt động cung cấp cái gì đó)","example":"The contract includes provisions for overtime.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/provision_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1560472354-b33ff0c44a43?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"noun"}'::jsonb),
  ('w7', 'lesson1', 7, '{"id":"w7","word":"resolve","familyWords":["resolution","resolvable"],"phonetic":"/rɪˈzɒlv/","meaning":"find a solution or answer","vietnameseMeaning":"giải quyết (tìm giải pháp hoặc câu trả lời)","example":"We resolved the issue quickly.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/resolve_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1559757148-5c350d0d3c56?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w8', 'lesson1', 8, '{"id":"w8","word":"specific","familyWords":["specification","specifically"],"phonetic":"/spəˈsɪf.ɪk/","meaning":"stated explicitly or in detail","vietnameseMeaning":"cụ thể (nêu rõ ràng hoặc chi tiết)","example":"Please give specific instructions.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/specific_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1460925895917-afdab827c52f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"adjective"}'::jsonb),
  ('w9', 'lesson1', 9, '{"id":"w9","word":"assure","familyWords":["assurance","reassure"],"phonetic":"/əˈʃɔːr/","meaning":"inform positively and with certainty and confidence","vietnameseMeaning":"đảm bảo (thông báo tích cực và chắc chắn)","example":"The manager assured us of the deadline.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/assure_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1552664730-d307ca884978?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w10', 'lesson1', 10, '{"id":"w10","word":"cancel","familyWords":["cancellation","cancellable"],"phonetic":"/ˈkæn.səl/","meaning":"declare null and void","vietnameseMeaning":"hủy bỏ (tuyên bố vô hiệu)","example":"The meeting was cancelled due to rain.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/cancel_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1576091160399-112ba8d25d1e?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w11', 'lesson1', 11, '{"id":"w11","word":"obligation","familyWords":["obligatory","oblige"],"phonetic":"/ˌɑː.b.ləˈɡeɪ.ʃən/","meaning":"the state of being bound to do or pay something","vietnameseMeaning":"nghĩa vụ (trạng thái bị ràng buộc phải làm hoặc trả gì đó)","example":"It''s my obligation to finish the report on time.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/obligation_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"noun"}'::jsonb),
  ('w12', 'lesson1', 12, '{"id":"w12","word":"obligatory","familyWords":["obligation"],"phonetic":"/əˈblɪɡ.ə.tɔːr.i/","meaning":"required by compulsion or convention","vietnameseMeaning":"bắt buộc (yêu cầu bởi sự ép buộc hoặc quy ước)","example":"Attendance at the meeting is obligatory.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/obligatory_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1559757148-5c350d0d3c56?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"adjective"}'::jsonb),
  ('w13', 'lesson1', 13, '{"id":"w13","word":"attract","familyWords":["attraction","attractive"],"phonetic":"/əˈtrækt/","meaning":"draw by appeal","vietnameseMeaning":"thu hút (hút theo sức hấp dẫn)","example":"The new campaign will attract more customers.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/attract_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1460925895917-afdab827c52f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w14', 'lesson1', 14, '{"id":"w14","word":"compare","familyWords":["comparison","comparable"],"phonetic":"/kəmˈper/","meaning":"to examine or look for the difference between two or more things","vietnameseMeaning":"so sánh (xem xét hoặc tìm sự khác biệt giữa hai hoặc nhiều thứ)","example":"Compare the prices before buying.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/compare_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w15', 'lesson1', 15, '{"id":"w15","word":"competition","familyWords":["compete","competitive"],"phonetic":"/ˌkɑːm.pəˈtɪʃ.ən/","meaning":"a contest or struggle","vietnameseMeaning":"cạnh tranh (cuộc thi hoặc đấu tranh)","example":"The competition is fierce in this market.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/competition_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1521737604893-d14cc237f11d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"noun"}'::jsonb),
  ('w16', 'lesson1', 16, '{"id":"w16","word":"consume","familyWords":["consumer","consumption"],"phonetic":"/kənˈsuːm/","meaning":"to absorb, to use up","vietnameseMeaning":"tiêu thụ (hấp thụ, sử dụng hết)","example":"Consumers consume more during holidays.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/consume_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1560472354-b33ff0c44a43?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w17', 'lesson1', 17, '{"id":"w17","word":"convince","familyWords":["conviction","convincing"],"phonetic":"/kənˈvɪns/","meaning":"to persuade","vietnameseMeaning":"thuyết phục (thuyết phục ai đó)","example":"The salesperson convinced me to buy it.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/convince_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1552664730-d307ca884978?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w18', 'lesson1', 18, '{"id":"w18","word":"currently","familyWords":["current"],"phonetic":"/ˈkɝː.ənt.li/","meaning":"now","vietnameseMeaning":"hiện tại (bây giờ)","example":"Currently, we are reviewing the proposal.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/currently_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1559757148-5c350d0d3c56?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"adverb"}'::jsonb),
  ('w19', 'lesson1', 19, '{"id":"w19","word":"fad","familyWords":[],"phonetic":"/fæd/","meaning":"a style, activity or interest which is very popular for a short period of time","vietnameseMeaning":"mốt (một phong cách, hoạt động hoặc sở thích phổ biến trong thời gian ngắn)","example":"That gadget was just a fad.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/fad_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1460925895917-afdab827c52f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"noun"}'::jsonb),
  ('w20', 'lesson1', 20, '{"id":"w20","word":"inspiration","familyWords":["inspire"],"phonetic":"/ˌɪn.spəˈreɪ.ʃən/","meaning":"a thing or person that arouses a feeling","vietnameseMeaning":"cảm hứng (một thứ hoặc người khơi dậy cảm xúc)","example":"The design drew inspiration from nature.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/inspiration_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"noun"}'::jsonb),
  ('w21', 'lesson1', 21, '{"id":"w21","word":"market","familyWords":["marketing","marketer"],"phonetic":"/ˈmɑːr.kɪt/","meaning":"to make goods available to buyers in a planned way which encourages people to buy more of them, for example by advertising","vietnameseMeaning":"tiếp thị (làm cho hàng hóa có sẵn cho người mua theo cách có kế hoạch khuyến khích mua nhiều hơn)","example":"We need to market the product better.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/market_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1521737604893-d14cc237f11d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
  ('w22', 'lesson1', 22, '{"id":"w22","word":"persuasion","familyWords":["persuade"],"phonetic":"/pɚˈsweɪ.ʒən/","meaning":"the power to influence; a deep belief","vietnameseMeaning":"sự thuyết phục (quyền lực ảnh hưởng; niềm tin sâu sắc)","example":"By persuasion, he got the team to agree.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/persuasion_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1552664730-d307ca884978?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"noun"}'::jsonb),
