  ('w481', 'lesson20', 28, '{"id":"w481","word":"attain","familyWords":["attainment","attainable"],"phonetic":"/əˈteɪn/","meaning":"to succeed in achieving something","vietnameseMeaning":"đạt được, giành được","example":"She finally attained her goal of becoming a film director.","audioSrc":"https://audio.oxforddictionaries.com/en/mp3/attain_us_1.mp3","imageSrc":"https://images.unsplash.com/photo-1544716278-ca5f311a598e?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80","partOfSpeech":"verb"}'::jsonb),
