insert into public.toeic_exam_questions (exam_id, question_id, sort_order, content) values
  ('test-01', 1, 1, '{"id":1,"type":"reading","partNumber":5,"text":"The regional director will arrive _____ the quarterly review begins.","options":["before","during","while","until"],"correctAnswer":0,"explanation":"“Before” is followed by a clause and means the arrival happens earlier than the review."}'::jsonb),
  ('test-01', 2, 2, '{"id":2,"type":"reading","partNumber":5,"text":"Please submit your travel receipts _____ Friday so that Finance can process them.","options":["by","among","since","along"],"correctAnswer":0,"explanation":"“By Friday” sets a deadline no later than Friday."}'::jsonb),
  ('test-01', 3, 3, '{"id":3,"type":"reading","partNumber":5,"text":"The new inventory system is _____ efficient than the previous one.","options":["much","more","most","many"],"correctAnswer":1,"explanation":"The comparative adjective “more efficient” compares the two systems."}'::jsonb),
  ('test-01', 4, 4, '{"id":4,"type":"reading","partNumber":5,"text":"Ms. Chen reviewed the proposal carefully before _____ it to the board.","options":["present","presented","presenting","presentation"],"correctAnswer":2,"explanation":"A possessive pronoun or preposition-like “before” is followed here by the gerund “presenting.”"}'::jsonb),
  ('test-01', 5, 5, '{"id":5,"type":"reading","partNumber":5,"text":"The shipment was delayed _____ severe weather near the port.","options":["because","because of","although","despite"],"correctAnswer":1,"explanation":"“Because of” is followed by the noun phrase “severe weather.”"}'::jsonb),
  ('test-01', 6, 6, '{"id":6,"type":"reading","partNumber":5,"text":"Customers may return unopened items within 30 days of _____.","options":["purchase","purchased","purchasing","purchases"],"correctAnswer":0,"explanation":"The noun “purchase” completes the phrase “within 30 days of purchase.”"}'::jsonb),
  ('test-01', 7, 7, '{"id":7,"type":"reading","partNumber":5,"text":"Each applicant must provide _____ references with the application.","options":["profession","professional","professionally","professionalism"],"correctAnswer":1,"explanation":"The adjective “professional” modifies the noun “references.”"}'::jsonb),
  ('test-01', 8, 8, '{"id":8,"type":"reading","partNumber":5,"text":"The conference room is unavailable, _____ the team will meet online.","options":["so","unless","whereas","despite"],"correctAnswer":0,"explanation":"“So” connects the room''s unavailability to its result."}'::jsonb),
  ('test-01', 9, 9, '{"id":9,"type":"reading","partNumber":5,"text":"Mr. Patel has worked in the accounting department _____ 2019.","options":["for","since","during","until"],"correctAnswer":1,"explanation":"“Since” is used with a specific starting point in time."}'::jsonb),
  ('test-01', 10, 10, '{"id":10,"type":"reading","partNumber":5,"text":"The manager asked that the final report _____ by noon.","options":["is completed","be completed","completes","will complete"],"correctAnswer":1,"explanation":"After “asked that,” a formal request uses the base-form subjunctive; the passive form is “be completed.”"}'::jsonb),
  ('test-01', 11, 11, '{"id":11,"type":"reading","partNumber":5,"text":"The company is seeking a candidate who can communicate _____ with international clients.","options":["effective","effectively","effectiveness","effect"],"correctAnswer":1,"explanation":"The adverb “effectively” modifies the verb “communicate.”"}'::jsonb),
  ('test-01', 12, 12, '{"id":12,"type":"reading","partNumber":5,"text":"The office renovation is expected to _____ next month.","options":["complete","completion","be completed","completing"],"correctAnswer":2,"explanation":"The renovation receives the action, so the passive infinitive “be completed” is needed."}'::jsonb),
  ('test-01', 13, 13, '{"id":13,"type":"reading","partNumber":6,"text":"What should employees do with equipment that needs to be moved?","options":["Leave it in the west wing","Label it by Friday afternoon","Take it home","Deliver it to the first floor"],"correctAnswer":1,"explanation":"The notice asks employees to label equipment that must be moved by Friday afternoon.","passage":"To: All staff\nFrom: Facilities Department\nSubject: West Wing Renovation\n\nBeginning Monday, the west wing will be closed for electrical repairs. Employees\nwho normally work in that area should use the temporary desks on the third floor.\nPlease label any equipment that must be moved by Friday afternoon. The project is\nexpected to be completed by the end of the month."}'::jsonb),
  ('test-01', 14, 14, '{"id":14,"type":"reading","partNumber":6,"text":"Where should west-wing employees work during the repairs?","options":["In Room 204","At the downtown showroom","At temporary desks on the third floor","From the west-wing reception area"],"correctAnswer":2,"explanation":"The notice says temporary desks are available on the third floor.","passage":"To: All staff\nFrom: Facilities Department\nSubject: West Wing Renovation\n\nBeginning Monday, the west wing will be closed for electrical repairs. Employees\nwho normally work in that area should use the temporary desks on the third floor.\nPlease label any equipment that must be moved by Friday afternoon. The project is\nexpected to be completed by the end of the month."}'::jsonb),
  ('test-01', 15, 15, '{"id":15,"type":"reading","partNumber":6,"text":"When is the renovation expected to finish?","options":["By Friday afternoon","Next Monday","At the end of the month","On June 15"],"correctAnswer":2,"explanation":"The notice expects the project to be completed by the end of the month.","passage":"To: All staff\nFrom: Facilities Department\nSubject: West Wing Renovation\n\nBeginning Monday, the west wing will be closed for electrical repairs. Employees\nwho normally work in that area should use the temporary desks on the third floor.\nPlease label any equipment that must be moved by Friday afternoon. The project is\nexpected to be completed by the end of the month."}'::jsonb),
  ('test-01', 16, 16, '{"id":16,"type":"reading","partNumber":6,"text":"Why was the meeting moved to Room 204?","options":["The sales figures were revised","The conference room is being renovated","The budget was finalized","The marketing proposal was delayed"],"correctAnswer":1,"explanation":"The email says the regular conference room is being renovated.","passage":"To: Ms. Lee\nFrom: Daniel Ortiz\nSubject: Quarterly planning meeting\n\nThank you for sending the revised sales figures. I have added them to the agenda\nfor Thursday''s planning meeting. Since the conference room is being renovated,\nwe will meet in Room 204 instead. Please bring the regional marketing proposal\nso the team can review it before the budget is finalized."}'::jsonb),
  ('test-01', 17, 17, '{"id":17,"type":"reading","partNumber":7,"text":"What is one feature of Northstar''s new printer?","options":["It uses less energy","It is available for immediate pickup","It prints in color only","It includes a year of free paper"],"correctAnswer":0,"explanation":"The announcement says the printer uses 30 percent less energy than the previous model.","passage":"Northstar Office Supply will introduce its new compact printer next month.\nThe device prints on both sides of the page and uses 30 percent less energy than\nthe previous model. Businesses that place an order before June 15 will receive\nfree delivery. Product demonstrations will be available at the downtown showroom\nevery weekday from 9 A.M. to 4 P.M."}'::jsonb),
  ('test-01', 18, 18, '{"id":18,"type":"reading","partNumber":7,"text":"By what date must customers order to receive free delivery?","options":["June 1","June 15","The end of the month","Any weekday"],"correctAnswer":1,"explanation":"Orders placed before June 15 qualify for free delivery.","passage":"Northstar Office Supply will introduce its new compact printer next month.\nThe device prints on both sides of the page and uses 30 percent less energy than\nthe previous model. Businesses that place an order before June 15 will receive\nfree delivery. Product demonstrations will be available at the downtown showroom\nevery weekday from 9 A.M. to 4 P.M."}'::jsonb),
  ('test-01', 19, 19, '{"id":19,"type":"reading","partNumber":7,"text":"Where can customers see a product demonstration?","options":["At the port","In Room 204","At the downtown showroom","At the third-floor desks"],"correctAnswer":2,"explanation":"Demonstrations are held at the downtown showroom on weekdays.","passage":"Northstar Office Supply will introduce its new compact printer next month.\nThe device prints on both sides of the page and uses 30 percent less energy than\nthe previous model. Businesses that place an order before June 15 will receive\nfree delivery. Product demonstrations will be available at the downtown showroom\nevery weekday from 9 A.M. to 4 P.M."}'::jsonb),
  ('test-01', 20, 20, '{"id":20,"type":"reading","partNumber":7,"text":"What does Daniel Ortiz ask Ms. Lee to bring to the meeting?","options":["Travel receipts","A regional marketing proposal","A product sample","A list of applicants"],"correctAnswer":1,"explanation":"Daniel asks Ms. Lee to bring the regional marketing proposal for review.","passage":"To: Ms. Lee\nFrom: Daniel Ortiz\nSubject: Quarterly planning meeting\n\nThank you for sending the revised sales figures. I have added them to the agenda\nfor Thursday''s planning meeting. Since the conference room is being renovated,\nwe will meet in Room 204 instead. Please bring the regional marketing proposal\nso the team can review it before the budget is finalized."}'::jsonb)
