create table if not exists public.courses (
  id integer primary key,
  sort_order integer not null unique,
  content jsonb not null check (jsonb_typeof(content) = 'object')
);

create table if not exists public.vocabulary_lessons (
  id text primary key,
  sort_order integer not null unique,
  content jsonb not null check (jsonb_typeof(content) = 'object')
);

create table if not exists public.vocabulary_words (
  id text primary key,
  lesson_id text not null references public.vocabulary_lessons (id) on delete cascade,
  sort_order integer not null,
  content jsonb not null check (jsonb_typeof(content) = 'object'),
  unique (lesson_id, sort_order)
);

create index if not exists vocabulary_words_lesson_order_idx
  on public.vocabulary_words (lesson_id, sort_order);

create table if not exists public.toeic_exams (
  id text primary key,
  sort_order integer not null unique,
  duration_seconds integer not null check (duration_seconds > 0),
  available boolean not null default false,
  content jsonb not null check (jsonb_typeof(content) = 'object')
);

create table if not exists public.toeic_exam_questions (
  exam_id text not null references public.toeic_exams (id) on delete cascade,
  question_id integer not null,
  sort_order integer not null,
  content jsonb not null check (jsonb_typeof(content) = 'object'),
  primary key (exam_id, question_id),
  unique (exam_id, sort_order)
);

alter table public.courses enable row level security;
grant select on table public.courses to anon, authenticated;
drop policy if exists "Public can read courses" on public.courses;
create policy "Public can read courses" on public.courses for select to anon, authenticated using (true);

alter table public.vocabulary_lessons enable row level security;
grant select on table public.vocabulary_lessons to anon, authenticated;
drop policy if exists "Public can read vocabulary_lessons" on public.vocabulary_lessons;
create policy "Public can read vocabulary_lessons" on public.vocabulary_lessons for select to anon, authenticated using (true);

alter table public.vocabulary_words enable row level security;
grant select on table public.vocabulary_words to anon, authenticated;
drop policy if exists "Public can read vocabulary_words" on public.vocabulary_words;
create policy "Public can read vocabulary_words" on public.vocabulary_words for select to anon, authenticated using (true);

alter table public.toeic_exams enable row level security;
grant select on table public.toeic_exams to anon, authenticated;
drop policy if exists "Public can read toeic_exams" on public.toeic_exams;
create policy "Public can read toeic_exams" on public.toeic_exams for select to anon, authenticated using (true);

alter table public.toeic_exam_questions enable row level security;
grant select on table public.toeic_exam_questions to anon, authenticated;
drop policy if exists "Public can read toeic_exam_questions" on public.toeic_exam_questions;
create policy "Public can read toeic_exam_questions" on public.toeic_exam_questions for select to anon, authenticated using (true);

on conflict do nothing;

